 p=OUT/htmlname;s=p.read_text(encoding='utf-8')
 s=s.replace("const BUILD_DATE = '2026-08-25'; // v101.121 / four-pass report tooling reconciliation R1","const BUILD_DATE = '2026-08-25'; // v101.122 / Hour-24 end-of-cycle state and action hierarchy R1",1)
