v=json.loads((OUT/'version.json').read_text());v.update({'app_version':VER,'cache_name':CACHE,'release_scope':'Narrow reader/progress UX successor: restores Hour-24 Hour-level actions, separates cycle state from Hour state, gates completed-cycle restart to canonical 24/24 Méditée progress, removes the disabled Hour-24 next control, aligns progress terminology, and removes redundant in-content Home actions where persistent Accueil was verified. Corpus, speech/presentation data, topology, storage schema, highlighting and Help are unchanged.','real_device_status':'Physical Samsung/iPhone/iPad, installed-PWA, true offline cold reopen, VoiceOver/TalkBack and live GitHub Pages exact-byte binding NOT_TESTED for v101.122.','overall_release_status':'LIMITED_PASS_STATIC_IF_FINAL_REOPEN_AUDITS_PASS','known_blockers':[],'external_open_gates':['physical iPad/iPhone/Samsung','Hour-24 end-of-cycle real-device layout and live Méditée transition','live GitHub Pages exact-byte binding','installed PWA update','true offline cold reopen','VoiceOver/TalkBack representative testing']});(OUT/'version.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
